-- ========================================================================================
-- ZooGuide Migration: Add TICKET_ORDERS Table and Order Link for Real QR Payment
-- ========================================================================================

CREATE TABLE IF NOT EXISTS public."TICKET_ORDERS" (
    "OrderId" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "OrderCode" VARCHAR(50) NOT NULL,
    "CustomerName" VARCHAR(100) NOT NULL,
    "CustomerEmail" VARCHAR(100) NOT NULL,
    "CustomerPhone" VARCHAR(20) NOT NULL,
    "TicketTypeId" INTEGER NOT NULL,
    "Quantity" INTEGER NOT NULL DEFAULT 1,
    "UnitPrice" NUMERIC(18,2) NOT NULL,
    "TotalAmount" NUMERIC(18,2) NOT NULL,
    "PaymentStatus" VARCHAR(20) NOT NULL DEFAULT 'Pending',
    "PaymentMethod" VARCHAR(50) NOT NULL DEFAULT 'VietQR',
    "PaymentDescription" VARCHAR(100) NOT NULL,
    "TransactionReference" VARCHAR(100) NULL,
    "QrCodeUrl" VARCHAR(500) NULL,
    "PaidAt" TIMESTAMPTZ NULL,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "UpdatedAt" TIMESTAMPTZ NULL,
    "ExpiresAt" TIMESTAMPTZ NOT NULL,

    CONSTRAINT "PK_TICKET_ORDERS" PRIMARY KEY ("OrderId"),
    CONSTRAINT "UQ_TicketOrders_OrderCode" UNIQUE ("OrderCode"),
    CONSTRAINT "FK_TicketOrders_TicketType" FOREIGN KEY ("TicketTypeId")
        REFERENCES public."TICKET_TYPES" ("TicketTypeId") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_TicketOrders_OrderCode" ON public."TICKET_ORDERS" ("OrderCode");
CREATE INDEX IF NOT EXISTS "IX_TicketOrders_PaymentStatus" ON public."TICKET_ORDERS" ("PaymentStatus");

ALTER TABLE public."TICKETS" ADD COLUMN IF NOT EXISTS "OrderId" INTEGER NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'FK_Tickets_TicketOrder'
    ) THEN
        ALTER TABLE public."TICKETS" 
        ADD CONSTRAINT "FK_Tickets_TicketOrder" FOREIGN KEY ("OrderId")
        REFERENCES public."TICKET_ORDERS" ("OrderId") ON DELETE SET NULL;
    END IF;
END $$;

GRANT ALL ON TABLE public."TICKET_ORDERS" TO anon;
GRANT ALL ON TABLE public."TICKET_ORDERS" TO authenticated;
GRANT ALL ON TABLE public."TICKET_ORDERS" TO service_role;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_class WHERE relname = 'TICKET_ORDERS_OrderId_seq'
    ) THEN
        GRANT ALL ON SEQUENCE public."TICKET_ORDERS_OrderId_seq" TO anon;
        GRANT ALL ON SEQUENCE public."TICKET_ORDERS_OrderId_seq" TO authenticated;
        GRANT ALL ON SEQUENCE public."TICKET_ORDERS_OrderId_seq" TO service_role;
    END IF;
END $$;
